INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Ablauforganisation nur für Produktionsprozesse relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dienstleistungen einsetzbar"}, {"text": "Ja", "correct": false, "because": "Nicht auf Produktion beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer guten Prozessstruktur?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Optimiert Abläufe"}, {"text": "Mitarbeiterreduktion", "correct": false, "because": "Nicht primär"}, {"text": "Softwareeinführung", "correct": false, "because": "Nur Mittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Ablauforganisation?', 5, '[{"text": "Prozessschritte", "correct": true, "because": "Definiert Reihenfolge"}, {"text": "Zeitplanung", "correct": true, "because": "Koordiniert Abläufe"}, {"text": "Mitarbeiteranzahl", "correct": false, "because": "Eher Aufbauorganisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ablauforganisation beschreibt Arbeitsteilung. b) Sie legt Verantwortlichkeiten fest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verantwortlichkeiten sind Aufbauorganisation"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung eines Prozesses?', 4, '[{"text": "Reihenfolge", "correct": false, "because": "Kern der Struktur"}, {"text": "Ressourceneinsatz", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Firmenlogo", "correct": true, "because": "Irrelevant für Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ablauforganisation auch Zeitabläufe umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Zeitliche Koordination enthalten"}, {"text": "Nein", "correct": false, "because": "Nicht nur räumlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wähle ich zur Prozessoptimierung?', 3, '[{"text": "Flussdiagramme", "correct": true, "because": "Visualisiert Abläufe"}, {"text": "Organigramme", "correct": false, "because": "Zeigt Hierarchie"}, {"text": "Checklisten", "correct": false, "because": "Nur Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Optimierung eines Ablaufs?', 5, '[{"text": "Reduzierung von Wartezeiten", "correct": true, "because": "Steigert Effizienz"}, {"text": "Klar definierte Schritte", "correct": true, "because": "Vermeidet Verwirrung"}, {"text": "Mitarbeiteranzahl", "correct": false, "because": "Eher Aufbau"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ablauforganisation spart Kosten. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Prozessgestaltung unwichtig?', 4, '[{"text": "Schrittfolge", "correct": false, "because": "Definiert Ablauf"}, {"text": "Ressourcennutzung", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Ablauforganisation statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Kann angepasst werden"}, {"text": "Ja", "correct": false, "because": "Flexibel bei Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine klare Prozessstruktur?', 4, '[{"text": "Weniger Fehler", "correct": true, "because": "Klarheit reduziert Missverständnisse"}, {"text": "Schnellere Abläufe", "correct": true, "because": "Optimiert Zeit"}, {"text": "Höhere Löhne", "correct": false, "because": "Kein direkter Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ablauforganisation nur Zeit spart. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kosten und Qualität verbessert"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Prozessplanung?', 3, '[{"text": "Effizienz", "correct": true, "because": "Kernziel der Struktur"}, {"text": "Mitarbeiterzufriedenheit", "correct": false, "because": "Sekundär"}, {"text": "Softwarewahl", "correct": false, "because": "Nur Werkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ablauforganisation reduziert Doppelarbeit. b) Sie ersetzt die Aufbauorganisation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Prozessstruktur?', 5, '[{"text": "Verzögerungen", "correct": true, "because": "Unklare Abläufe"}, {"text": "Höhere Kosten", "correct": true, "because": "Ineffizienz"}, {"text": "Bessere Qualität", "correct": false, "because": "Qualität leidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Ablauforganisation unwichtig?', 3, '[{"text": "Zeitliche Abfolge", "correct": false, "because": "Kern der Planung"}, {"text": "Ressourcenzuordnung", "correct": false, "because": "Wichtig für Umsetzung"}, {"text": "Mitarbeiterhierarchie", "correct": true, "because": "Aufbauorganisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Ablauforganisation automatisiert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Tools möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ablauforganisation Qualität sichert?', 2, '[{"text": "Ja", "correct": true, "because": "Klarheit steigert Qualität"}, {"text": "Nein", "correct": false, "because": "Indirekt durch Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für Prozessvisualisierung?', 4, '[{"text": "Ablaufdiagramme", "correct": true, "because": "Zeigt Schritte klar"}, {"text": "Hierarchiediagramme", "correct": false, "because": "Für Aufbau"}, {"text": "Tabellen", "correct": false, "because": "Weniger anschaulich"}]');
